// ─── Dodo Payments Card ───────────────────────────────────────────────────────

const DodoCard = ({ integration, config, onTest, testing, onConfigSaved }: any) => {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [environment, setEnvironment] = useState<string>(config?.dodo_payments_environment || "test_mode");

  const envChanged = environment !== (config?.dodo_payments_environment || "test_mode");

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({ dodo_payments_environment: environment } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Dodo environment updated");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "dodo", environment });
      onConfigSaved?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">

      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-emerald-500/10 flex items-center justify-center shrink-0">
              <CreditCard className="h-5 w-5 text-emerald-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">Dodo Payments</p>
              <p className="text-xs text-muted-foreground">Credit packs · Subscriptions · Webhooks</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge
              variant={environment === "live_mode" ? "default" : "secondary"}
              className={`text-[10px] shrink-0 ${environment === "live_mode" ? "bg-emerald-600 hover:bg-emerald-600" : ""}`}
            >
              {environment === "live_mode" ? "Live" : "Test Mode"}
            </Badge>
            <StatusBadge status={integration?.last_test_status} />
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Environment selector */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Environment</p>
            <div className="rounded-lg border p-4 space-y-3">
              <div>
                <Label className="text-xs font-medium">Active Environment</Label>
                <p className="text-xs text-muted-foreground mb-2">Controls which Dodo API endpoint all functions call</p>
                <div className="flex gap-2">
                  <Select value={environment} onValueChange={setEnvironment}>
                    <SelectTrigger className="flex-1">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="test_mode">
                        <div className="flex items-center gap-2">
                          <FlaskConical className="h-3.5 w-3.5 text-muted-foreground" />
                          Test Mode — sandbox, no real charges
                        </div>
                      </SelectItem>
                      <SelectItem value="live_mode">
                        <div className="flex items-center gap-2">
                          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
                          Live Mode — production, real payments
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                  <Button size="sm" onClick={save} disabled={saving || !envChanged} variant={envChanged ? "default" : "outline"}>
                    {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
                  </Button>
                </div>
                {environment === "live_mode" && (
                  <p className="text-xs text-amber-600 bg-amber-500/10 rounded-md px-3 py-2 mt-2">
                    ⚠️ Live mode charges real money. Also update <code className="font-mono">DODO_PAYMENTS_ENVIRONMENT</code> in Supabase Secrets to match.
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* Secrets reference */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">API Credentials</p>
            <p className="text-xs text-muted-foreground mb-2">These are stored as Supabase Edge Function Secrets (write-only, cannot be read from UI)</p>
            <div className="rounded-lg border divide-y px-3">
              <SecretRow name="DODO_PAYMENTS_API_KEY" description="Your Dodo API key from Dashboard → Developers → API Keys" />
              <SecretRow name="DODO_PAYMENTS_WEBHOOK_SECRET" description="Webhook signing secret from Dashboard → Developers → Webhooks" />
              <SecretRow name="DODO_PAYMENTS_ENVIRONMENT" description="Must match the environment selected above (test_mode or live_mode)" />
            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Sign up at <a href="https://dashboard.dodopayments.com" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">dashboard.dodopayments.com</a> and complete account setup</>} />
              <Step n={2} text={<>Go to <strong>Developers → API Keys</strong> and create a new API key. Copy it.</>} />
              <Step n={3} text={<>Go to <strong>Developers → Webhooks</strong>, create a webhook endpoint pointing to your Supabase <code className="bg-background px-1 rounded text-xs">dodo-webhook</code> function URL. Copy the signing secret.</>} />
              <Step n={4} text={<>In Supabase dashboard → <strong>Project Settings → Edge Functions → Secrets</strong>, add:<br />
                <span className="block mt-1 space-y-0.5 ml-1">
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">DODO_PAYMENTS_API_KEY</code> = your API key</span>
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">DODO_PAYMENTS_WEBHOOK_SECRET</code> = your webhook secret</span>
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">DODO_PAYMENTS_ENVIRONMENT</code> = <code className="bg-background px-1 rounded">test_mode</code></span>
