// ─── Postmark Card ────────────────────────────────────────────────────────────

const PostmarkCard = ({ integration, config, onTest, testing, onConfigSaved }: any) => {
  const [open, setOpen] = useState(false);
  const [showToken, setShowToken] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    postmark_api_token: config?.postmark_api_token || "",
    email_from_address: config?.email_from_address || "noreply@rankora.co",
    email_from_name: config?.email_from_name || "Rankora",
    outbound_email_enabled: config?.outbound_email_enabled ?? false,
    email_notify_ranking_complete: config?.email_notify_ranking_complete ?? true,
    email_notify_resume_received: config?.email_notify_resume_received ?? true,
    inbound_email_domain: config?.inbound_email_domain || "inbound.rankora.co",
  });

  const save = async () => {
    if (!form.email_from_address.includes("@")) { toast.error("Enter a valid from address"); return; }
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({
          postmark_api_token: form.postmark_api_token || null,
          email_from_address: form.email_from_address,
          email_from_name: form.email_from_name,
          outbound_email_enabled: form.outbound_email_enabled,
          email_notify_ranking_complete: form.email_notify_ranking_complete,
          email_notify_resume_received: form.email_notify_resume_received,
          inbound_email_domain: form.inbound_email_domain,
        } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Postmark settings saved");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "postmark" });
      onConfigSaved?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const maskedToken = config?.postmark_api_token
    ? config.postmark_api_token.slice(0, 6) + "••••••••••••••••" + config.postmark_api_token.slice(-4)
    : null;

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">

      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-blue-500/10 flex items-center justify-center shrink-0">
              <Mail className="h-5 w-5 text-blue-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">Postmark</p>
              <p className="text-xs text-muted-foreground">Transactional email · Inbound parsing</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant={config?.outbound_email_enabled ? "default" : "secondary"} className="text-[10px] shrink-0">
              {config?.outbound_email_enabled ? "Outbound On" : "Outbound Off"}
            </Badge>
            <StatusBadge status={integration?.last_test_status} />
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Current config summary (read-only quick view) */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Current Config</p>
            <div className="rounded-lg border divide-y px-3">
              <InfoRow label="API Token" value={maskedToken ? <span className="font-mono text-xs">{maskedToken}</span> : <span className="text-muted-foreground italic text-xs">Not configured</span>} />
              <InfoRow label="From Address" value={config?.email_from_address || "noreply@rankora.co"} />
              <InfoRow label="From Name" value={config?.email_from_name || "Rankora"} />
              <InfoRow label="Inbound Domain" value={<span className="font-mono text-xs">{config?.inbound_email_domain || "inbound.rankora.co"}</span>} />
            </div>
          </div>

          {/* Edit form */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Edit Settings</p>
            <div className="space-y-4 rounded-lg border p-4">

              {/* API Token */}
              <div>
                <Label className="text-xs font-medium">Server API Token</Label>
                <p className="text-xs text-muted-foreground mb-1.5">Found in Postmark → Your Server → API Tokens</p>
                <div className="flex gap-2">
                  <Input
                    type={showToken ? "text" : "password"}
                    value={form.postmark_api_token}
                    onChange={(e) => setForm({ ...form, postmark_api_token: e.target.value })}
                    placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
                    className="font-mono text-sm flex-1"
                  />
                  <Button variant="outline" size="icon" onClick={() => setShowToken(!showToken)} title={showToken ? "Hide" : "Show"}>
                    {showToken ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </Button>
                </div>
              </div>

              {/* From address + name */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs font-medium">From Address</Label>
                  <Input
                    value={form.email_from_address}
                    onChange={(e) => setForm({ ...form, email_from_address: e.target.value })}
                    placeholder="noreply@rankora.co"
                    className="mt-1.5 text-sm"
                  />
                </div>
                <div>
                  <Label className="text-xs font-medium">From Name</Label>
                  <Input
                    value={form.email_from_name}
                    onChange={(e) => setForm({ ...form, email_from_name: e.target.value })}
                    placeholder="Rankora"
                    className="mt-1.5 text-sm"
                  />
                </div>
              </div>

              {/* Inbound domain */}
              <div>
                <Label className="text-xs font-medium">Inbound Email Domain</Label>
                <p className="text-xs text-muted-foreground mb-1.5">Domain that receives forwarded resumes via Postmark inbound</p>
                <Input
                  value={form.inbound_email_domain}
                  onChange={(e) => setForm({ ...form, inbound_email_domain: e.target.value })}
                  placeholder="inbound.rankora.co"
                  className="font-mono text-sm"
                />
              </div>

              <Separator />

              {/* Toggles */}
              <div className="space-y-3">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Notifications</p>
                {[
                  { key: "outbound_email_enabled", label: "Enable outbound emails", desc: "Send emails via Postmark (ranking complete, resume received)" },
                  { key: "email_notify_ranking_complete", label: "Ranking complete notification", desc: "Email candidate when ranking finishes" },
                  { key: "email_notify_resume_received", label: "Resume received notification", desc: "Email sender confirmation when resume is ingested" },
                ].map(({ key, label, desc }) => (
                  <div key={key} className="flex items-start justify-between gap-4">
                    <div>
                      <p className="text-sm font-medium">{label}</p>
                      <p className="text-xs text-muted-foreground">{desc}</p>
                    </div>
                    <Switch
                      checked={(form as any)[key]}
                      onCheckedChange={(c) => setForm({ ...form, [key]: c })}
                    />
                  </div>
                ))}
              </div>

              <Button size="sm" onClick={save} disabled={saving} className="w-full">
                {saving ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Save className="h-3.5 w-3.5 mr-1.5" />}
                Save Postmark Settings
              </Button>
            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Sign up at <a href="https://postmarkapp.com" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">postmarkapp.com</a> and create a Server</>} />
              <Step n={2} text={<>In your server, go to <strong>API Tokens</strong> tab and copy the <strong>Server API Token</strong></>} />
              <Step n={3} text="Paste the token in the API Token field above and click Save" />
              <Step n={4} text={<>Add your sender email (<code className="bg-background px-1 rounded text-xs">noreply@rankora.co</code>) in <strong>Sender Signatures</strong> and verify it</>} />
              <Step n={5} text={<>For inbound email: go to <strong>Inbound</strong> tab and set webhook URL to your Supabase email-ingest function URL</>} />
