            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant={enabled ? "default" : "secondary"} className={`text-[10px] shrink-0 ${enabled ? "bg-green-600 hover:bg-green-600" : ""}`}>
              {enabled ? "Active" : "Disabled"}
            </Badge>
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Toggle */}
          <div className="flex items-start justify-between gap-4">
            <div>
              <p className="text-sm font-medium">Enable chat widget</p>
              <p className="text-xs text-muted-foreground">When enabled, the embed code below will be injected on all pages</p>
            </div>
            <Switch checked={enabled} onCheckedChange={setEnabled} />
          </div>

          {/* Embed code */}
          <div>
            <Label className="text-xs font-medium">Embed Code</Label>
            <p className="text-xs text-muted-foreground mb-1.5">
              Paste the full embed/script code from your chat provider (e.g. Intercom, Crisp, Tawk.to, Zendesk, Drift)
            </p>
            <Textarea
              value={code}
              onChange={(e) => setCode(e.target.value)}
              placeholder={'<script src="https://your-chat-provider.com/widget.js"></script>'}
              className="font-mono text-xs min-h-[120px]"
            />
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text="Sign up with your preferred chat widget provider (Intercom, Crisp, Tawk.to, etc.)" />
              <Step n={2} text="Find the embed/installation code in your provider's dashboard (usually a script tag)" />
              <Step n={3} text="Paste the full embed code in the text area above" />
              <Step n={4} text="Toggle the switch to enable it, then click Save" />
            </div>
          </div>

          <Button size="sm" onClick={save} disabled={saving} className="w-full">
            {saving ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Save className="h-3.5 w-3.5 mr-1.5" />}
