import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import { Textarea } from "@/components/ui/textarea";
import {
  CheckCircle2, XCircle, Loader2, ExternalLink, Mail, Brain, CreditCard,
  ChevronDown, Eye, EyeOff, Save, FlaskConical, RefreshCw, MessageCircle,
} from "lucide-react";
import { useState } from "react";
import { logAuditAction } from "@/lib/auditLog";

// ─── Shared helpers ───────────────────────────────────────────────────────────

const StatusBadge = ({ status }: { status: string | null }) => {
  if (status === "success")
    return <Badge className="gap-1 bg-green-600 hover:bg-green-600 text-white text-xs shrink-0"><CheckCircle2 className="h-3 w-3" />Connected</Badge>;
  if (status === "failed")
    return <Badge variant="destructive" className="gap-1 text-xs shrink-0"><XCircle className="h-3 w-3" />Failed</Badge>;
  return <Badge variant="secondary" className="text-xs shrink-0">Not tested</Badge>;
};

const Step = ({ n, text }: { n: number; text: React.ReactNode }) => (
  <div className="flex gap-3">
    <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[11px] font-semibold text-primary mt-0.5">{n}</span>
    <p className="text-sm text-muted-foreground leading-relaxed">{text}</p>
  </div>
);

const SecretRow = ({ name, description }: { name: string; description?: string }) => (
  <div className="flex items-start justify-between gap-3 py-2">
    <div>
      <code className="text-xs bg-muted px-1.5 py-0.5 rounded font-mono">{name}</code>
      {description && <p className="text-xs text-muted-foreground mt-0.5">{description}</p>}
    </div>
    <Badge variant="outline" className="text-[10px] shrink-0">Env Secret</Badge>
  </div>
);

const InfoRow = ({ label, value }: { label: string; value: React.ReactNode }) => (
  <div className="flex items-center justify-between py-1.5 text-sm">
    <span className="text-muted-foreground">{label}</span>
    <span className="font-medium text-right">{value}</span>
  </div>
);

// ─── OpenAI Card ─────────────────────────────────────────────────────────────

const OpenAICard = ({ integration, onTest, testing }: any) => {
  const [open, setOpen] = useState(false);

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="rounded-xl border bg-card shadow-sm overflow-hidden">

      {/* Header — always visible, click to expand */}
      <CollapsibleTrigger asChild>
        <button className="w-full flex items-center justify-between p-5 hover:bg-muted/30 transition-colors text-left">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-violet-500/10 flex items-center justify-center shrink-0">
              <Brain className="h-5 w-5 text-violet-600" />
            </div>
            <div>
              <p className="font-semibold text-sm">OpenAI</p>
              <p className="text-xs text-muted-foreground">GPT-4o · Resume ranking · JD analysis</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <StatusBadge status={integration?.last_test_status} />
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Secret info */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">API Credentials</p>
            <div className="rounded-lg border divide-y">
              <div className="px-3">
                <SecretRow name="OPENAI_API_KEY" description="Your OpenAI secret key — set in Supabase Edge Function Secrets" />
              </div>
            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Go to <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">platform.openai.com/api-keys</a> and create a new secret key</>} />
              <Step n={2} text={<>In your Supabase dashboard → <strong>Project Settings → Edge Functions → Secrets</strong></>} />
              <Step n={3} text={<>Click <strong>Add new secret</strong>, set name <code className="bg-background px-1 rounded text-xs">OPENAI_API_KEY</code> and paste your key</>} />
              <Step n={4} text="Click Test Connection below — status badge will turn green on success" />
            </div>
          </div>

          {/* Used by */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Used By</p>
            <div className="flex flex-wrap gap-1.5">
              {["rank-resumes", "analyze-jd", "evaluate-model"].map(fn => (
                <Badge key={fn} variant="outline" className="text-xs font-mono">{fn}</Badge>
              ))}
            </div>
          </div>

          <Separator />

          {/* Footer actions */}
          <div className="flex items-center justify-between">
            <p className="text-xs text-muted-foreground">
              {integration?.last_tested_at
                ? <>Last tested: {new Date(integration.last_tested_at).toLocaleString()}</>
                : "Never tested"}
            </p>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={() => onTest("OPENAI_API_KEY")} disabled={testing === "OPENAI_API_KEY"}>
                {testing === "OPENAI_API_KEY"
                  ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                  : <FlaskConical className="h-3.5 w-3.5 mr-1.5" />}
                Test Connection
              </Button>
              <Button variant="ghost" size="sm" asChild>
                <a href="https://platform.openai.com" target="_blank" rel="noopener noreferrer">
                  <ExternalLink className="h-3.5 w-3.5 mr-1.5" />Dashboard
                </a>
              </Button>
            </div>
          </div>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
};

// ─── Postmark Card ────────────────────────────────────────────────────────────

const PostmarkCard = ({ integration, config, onTest, testing, onConfigSaved }: any) => {
  const [open, setOpen] = useState(false);
  const [showToken, setShowToken] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    postmark_api_token: config?.postmark_api_token || "",
    email_from_address: config?.email_from_address || "noreply@rankora.co",
    email_from_name: config?.email_from_name || "Rankora",
    outbound_email_enabled: config?.outbound_email_enabled ?? false,
    email_notify_ranking_complete: config?.email_notify_ranking_complete ?? true,
    email_notify_resume_received: config?.email_notify_resume_received ?? true,
    inbound_email_domain: config?.inbound_email_domain || "inbound.rankora.co",
  });

  const save = async () => {
    if (!form.email_from_address.includes("@")) { toast.error("Enter a valid from address"); return; }
    setSaving(true);
    try {
      const { error } = await supabase
        .from("platform_config")
        .update({
          postmark_api_token: form.postmark_api_token || null,
          email_from_address: form.email_from_address,
          email_from_name: form.email_from_name,
          outbound_email_enabled: form.outbound_email_enabled,
          email_notify_ranking_complete: form.email_notify_ranking_complete,
          email_notify_resume_received: form.email_notify_resume_received,
          inbound_email_domain: form.inbound_email_domain,
        } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Postmark settings saved");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "postmark" });
      onConfigSaved?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
