          </div>
          <div className="flex items-center gap-2">
            <Badge variant={enabled ? "default" : "secondary"} className={`text-[10px] shrink-0 ${enabled ? "bg-green-600 hover:bg-green-600" : ""}`}>
              {enabled ? "Active" : "Disabled"}
            </Badge>
            <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
          </div>
        </button>
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="px-5 pb-5 space-y-5">
          <Separator />

          {/* Toggle */}
          <div className="flex items-start justify-between gap-4">
            <div>
              <p className="text-sm font-medium">Enable chat widget</p>
              <p className="text-xs text-muted-foreground">When enabled, the embed code below will be injected on all pages</p>
            </div>
            <Switch checked={enabled} onCheckedChange={setEnabled} />
          </div>

          {/* Embed code */}
          <div>
            <Label className="text-xs font-medium">Embed Code</Label>
            <p className="text-xs text-muted-foreground mb-1.5">
              Paste the full embed/script code from your chat provider (e.g. Intercom, Crisp, Tawk.to, Zendesk, Drift)
            </p>
            <Textarea
              value={code}
              onChange={(e) => setCode(e.target.value)}
              placeholder={'<script src="https://your-chat-provider.com/widget.js"></script>'}
              className="font-mono text-xs min-h-[120px]"
            />
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text="Sign up with your preferred chat widget provider (Intercom, Crisp, Tawk.to, etc.)" />
              <Step n={2} text="Find the embed/installation code in your provider's dashboard (usually a script tag)" />
              <Step n={3} text="Paste the full embed code in the text area above" />
              <Step n={4} text="Toggle the switch to enable it, then click Save" />
            </div>
          </div>

          <Button size="sm" onClick={save} disabled={saving} className="w-full">
            {saving ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Save className="h-3.5 w-3.5 mr-1.5" />}
            Save Chat Widget Settings
          </Button>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
};

// ─── Main Tab ─────────────────────────────────────────────────────────────────

const IntegrationsTab = ({ onNavigateToEmail }: { onNavigateToEmail?: () => void }) => {
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations } = useQuery({
    queryKey: ["admin_integrations"],
    queryFn: async () => {
      const { data, error } = await supabase.from("integrations").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const { data: config, refetch: refetchConfig } = useQuery({
    queryKey: ["platform_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: keyName },
      });
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  const getIntegration = (key: string) => integrations?.find((i: any) => i.key_name === key);
  const handleConfigSaved = () => {
    refetchConfig();
    qc.invalidateQueries({ queryKey: ["platform_config"] });
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-xl font-semibold">Integrations</h2>
        <p className="text-sm text-muted-foreground mt-1">Click any integration to expand configuration details, edit settings, and view the setup guide.</p>
      </div>
      <div className="space-y-3">
        <OpenAICard
          integration={getIntegration("OPENAI_API_KEY")}
          onTest={testIntegration}
          testing={testing}
        />
        <PostmarkCard
          integration={getIntegration("POSTMARK_API_TOKEN")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onConfigSaved={handleConfigSaved}
          onNavigateToEmail={onNavigateToEmail}
        />
        <DodoCard
          integration={getIntegration("DODO_PAYMENTS_API_KEY")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onConfigSaved={handleConfigSaved}
        />
      </div>
    </div>
  );
};

export default IntegrationsTab;

