                  <Select value={environment} onValueChange={setEnvironment}>
                    <SelectTrigger className="flex-1">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="test_mode">
                        <div className="flex items-center gap-2">
                          <FlaskConical className="h-3.5 w-3.5 text-muted-foreground" />
                          Test Mode — sandbox, no real charges
                        </div>
                      </SelectItem>
                      <SelectItem value="live_mode">
                        <div className="flex items-center gap-2">
                          <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />
                          Live Mode — production, real payments
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                  <Button size="sm" onClick={save} disabled={saving || !envChanged} variant={envChanged ? "default" : "outline"}>
                    {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
                  </Button>
                </div>
                {environment === "live_mode" && (
                  <p className="text-xs text-amber-600 bg-amber-500/10 rounded-md px-3 py-2 mt-2">
