        </div>
      </CollapsibleContent>
    </Collapsible>
  );
};

// ─── Main Tab ─────────────────────────────────────────────────────────────────

const IntegrationsTab = ({ onNavigateToEmail }: { onNavigateToEmail?: () => void }) => {
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations } = useQuery({
    queryKey: ["admin_integrations"],
    queryFn: async () => {
      const { data, error } = await supabase.from("integrations").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const { data: config, refetch: refetchConfig } = useQuery({
    queryKey: ["platform_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: keyName },
      });
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  const getIntegration = (key: string) => integrations?.find((i: any) => i.key_name === key);
  const handleConfigSaved = () => {
    refetchConfig();
    qc.invalidateQueries({ queryKey: ["platform_config"] });
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-xl font-semibold">Integrations</h2>
        <p className="text-sm text-muted-foreground mt-1">Click any integration to expand configuration details, edit settings, and view the setup guide.</p>
      </div>
      <div className="space-y-3">
        <OpenAICard
          integration={getIntegration("OPENAI_API_KEY")}
          onTest={testIntegration}
          testing={testing}
        />
        <PostmarkCard
          integration={getIntegration("POSTMARK_API_TOKEN")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onConfigSaved={handleConfigSaved}
          onNavigateToEmail={onNavigateToEmail}
        />
        <DodoCard
          integration={getIntegration("DODO_PAYMENTS_API_KEY")}
          config={config}
          onTest={testIntegration}
          testing={testing}
          onConfigSaved={handleConfigSaved}
        />
        <ChatWidgetCard
          config={config}
          onConfigSaved={handleConfigSaved}
        />
      </div>
    </div>
  );
};

export default IntegrationsTab;

