-- Hiring Stage Tracker: tracks current stage per candidate per job
CREATE TABLE IF NOT EXISTS public.candidate_stages (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  resume_id uuid NOT NULL REFERENCES public.resumes(id) ON DELETE CASCADE,
  job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,
  stage text NOT NULL DEFAULT 'applied'
    CHECK (stage IN ('applied','screened','interview','offer','hired','rejected')),
  updated_at timestamptz DEFAULT now(),
  updated_by uuid REFERENCES auth.users(id),
  UNIQUE(resume_id, job_id)
);

-- Stage history: timestamped log of all transitions
CREATE TABLE IF NOT EXISTS public.stage_history (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  resume_id uuid NOT NULL REFERENCES public.resumes(id) ON DELETE CASCADE,
  job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,
  from_stage text,
  to_stage text NOT NULL,
  changed_at timestamptz DEFAULT now(),
  changed_by uuid REFERENCES auth.users(id)
);

-- Enable RLS
ALTER TABLE public.candidate_stages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stage_history ENABLE ROW LEVEL SECURITY;

-- RLS: Users can manage stages for jobs they own
CREATE POLICY "Users can view stages for own jobs" ON public.candidate_stages
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.jobs WHERE jobs.id = candidate_stages.job_id AND jobs.user_id = auth.uid())
  );

CREATE POLICY "Users can insert stages for own jobs" ON public.candidate_stages
  FOR INSERT WITH CHECK (
    EXISTS (SELECT 1 FROM public.jobs WHERE jobs.id = candidate_stages.job_id AND jobs.user_id = auth.uid())
  );

CREATE POLICY "Users can update stages for own jobs" ON public.candidate_stages
  FOR UPDATE USING (
    EXISTS (SELECT 1 FROM public.jobs WHERE jobs.id = candidate_stages.job_id AND jobs.user_id = auth.uid())
  );

CREATE POLICY "Users can delete stages for own jobs" ON public.candidate_stages
  FOR DELETE USING (
    EXISTS (SELECT 1 FROM public.jobs WHERE jobs.id = candidate_stages.job_id AND jobs.user_id = auth.uid())
  );

-- RLS for stage_history
CREATE POLICY "Users can view stage history for own jobs" ON public.stage_history
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.jobs WHERE jobs.id = stage_history.job_id AND jobs.user_id = auth.uid())
  );

CREATE POLICY "Users can insert stage history for own jobs" ON public.stage_history
  FOR INSERT WITH CHECK (
    EXISTS (SELECT 1 FROM public.jobs WHERE jobs.id = stage_history.job_id AND jobs.user_id = auth.uid())
  );

-- Indexes
CREATE INDEX IF NOT EXISTS idx_candidate_stages_job_id ON public.candidate_stages(job_id);
CREATE INDEX IF NOT EXISTS idx_candidate_stages_resume_id ON public.candidate_stages(resume_id);
CREATE INDEX IF NOT EXISTS idx_stage_history_job_id ON public.stage_history(job_id);
CREATE INDEX IF NOT EXISTS idx_stage_history_resume_id ON public.stage_history(resume_id);

COMMENT ON TABLE public.candidate_stages IS 'Current hiring stage per candidate per job (applied→screened→interview→offer→hired/rejected)';
COMMENT ON TABLE public.stage_history IS 'Timestamped log of all hiring stage transitions';

