import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export type HiringStage = "applied" | "screened" | "interview" | "offer" | "hired" | "rejected";

export const STAGE_ORDER: HiringStage[] = ["applied", "screened", "interview", "offer", "hired"];

export interface CandidateStage {
  id: string;
  resume_id: string;
  job_id: string;
  stage: HiringStage;
  updated_at: string;
}

export function useStages(jobId: string | null) {
  return useQuery({
    queryKey: ["candidate-stages", jobId],
    queryFn: async (): Promise<CandidateStage[]> => {
      if (!jobId) return [];
      try {
        const { data, error } = await (supabase as any)
          .from("candidate_stages")
          .select("id, resume_id, job_id, stage, updated_at")
          .eq("job_id", jobId);
        if (error) {
          // Graceful fallback if table doesn't exist (migration not applied)
          if (error.message?.includes("schema cache") || error.message?.includes("does not exist") || error.code === "42P01") {
            return [];
          }
          throw error;
        }
        return (data ?? []) as CandidateStage[];
      } catch (err: any) {
        if (err?.message?.includes("schema cache") || err?.message?.includes("does not exist")) {
          return [];
        }
        throw err;
      }
    },
    enabled: !!jobId,
    retry: false,
  });
}

export function useUpdateStage() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({
      resumeId,
      jobId,
      newStage,
      currentStage,
    }: {
      resumeId: string;
      jobId: string;
      newStage: HiringStage;
      currentStage?: HiringStage | null;
    }) => {
      const { error: upsertError } = await (supabase as any)
        .from("candidate_stages")
        .upsert(
          {
            resume_id: resumeId,
            job_id: jobId,
            stage: newStage,
            updated_at: new Date().toISOString(),
            updated_by: user?.id,
          },
          { onConflict: "resume_id,job_id" }
        );
      if (upsertError) throw upsertError;

      // Log transition (non-critical, don't block on failure)
      try {
        await (supabase as any)
          .from("stage_history")
          .insert({
            resume_id: resumeId,
            job_id: jobId,
            from_stage: currentStage || null,
            to_stage: newStage,
            changed_by: user?.id,
          });
      } catch { /* history logging is non-critical */ }
    },
    onMutate: async (variables) => {
      await queryClient.cancelQueries({ queryKey: ["candidate-stages", variables.jobId] });
      const previous = queryClient.getQueryData<CandidateStage[]>(["candidate-stages", variables.jobId]);
      queryClient.setQueryData<CandidateStage[]>(["candidate-stages", variables.jobId], (old) => {
        const entry: CandidateStage = { id: "optimistic", resume_id: variables.resumeId, job_id: variables.jobId, stage: variables.newStage, updated_at: new Date().toISOString() };
        if (!old) return [entry];
        const exists = old.find((s) => s.resume_id === variables.resumeId);
        if (exists) return old.map((s) => s.resume_id === variables.resumeId ? { ...s, stage: variables.newStage, updated_at: new Date().toISOString() } : s);
        return [...old, entry];
      });
      return { previous };
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["candidate-stages", variables.jobId] });
      toast.success("Stage updated");
    },
    onError: (error: Error, variables, context) => {
      if (context?.previous) {
        queryClient.setQueryData(["candidate-stages", variables.jobId], context.previous);
      }
      if (error.message?.includes("schema cache") || error.message?.includes("does not exist")) {
        toast.error("Stage tracking requires database migration. Run: supabase db push");
      } else {
        toast.error(error.message || "Failed to update stage");
      }
    },
  });
}

export function useStageSummary(jobId: string | null) {
  const { data: stages } = useStages(jobId);

  const summary: Record<HiringStage, number> = {
    applied: 0, screened: 0, interview: 0, offer: 0, hired: 0, rejected: 0,
  };

  if (stages) {
    stages.forEach((s) => {
      if (summary[s.stage] !== undefined) {
        summary[s.stage]++;
      }
    });
  }

  return summary;
}

