            <div>
              <div className="flex items-center gap-2 mb-6">
                <div className="h-px flex-1 bg-border" />
                <span className="text-xs font-semibold uppercase tracking-widest text-muted-foreground px-3">How It Works</span>
                <div className="h-px flex-1 bg-border" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {[
                  {
                    step: "01",
                    icon: Brain,
                    title: "AI Reads the Job",
                    desc: "Paste any job description. GPT-4o extracts must-haves, nice-to-haves, seniority level, and builds a custom scoring rubric — automatically.",
                    detail: "No templates. No setup.",
                  },
                  {
                    step: "02",
                    icon: Upload,
