import { useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface SeoSettings {
  id: string;
  site_title: string;
  site_description: string;
  site_keywords: string;
  canonical_url: string;
  og_title: string;
  og_description: string;
  og_image_url: string;
  og_type: string;
  og_site_name: string;
  twitter_card: string;
  twitter_site: string;
  twitter_creator: string;
  twitter_image_url: string;
  robots_txt: string;
  meta_robots: string;
  googlebot: string;
  bingbot: string;
  sitemap_enabled: boolean;
  sitemap_changefreq: string;
  sitemap_priority: number;
  structured_data_enabled: boolean;
  organization_name: string;
  organization_url: string;
  organization_logo_url: string;
  organization_description: string;
  google_analytics_id: string;
  google_search_console_id: string;
  bing_webmaster_id: string;
  facebook_app_id: string;
  theme_color: string;
  manifest_enabled: boolean;
  created_at: string;
  updated_at: string;
}

export interface SeoPage {
  id: string;
  page_path: string;
  page_name: string;
  title: string;
  description: string;
  keywords: string;
  og_title: string;
  og_description: string;
  og_image_url: string;
  meta_robots: string;
  canonical_url: string;
  structured_data_json: Record<string, any>;
  changefreq: string;
  priority: number;
  include_in_sitemap: boolean;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export function useSeoSettings() {
  const qc = useQueryClient();

  const { data: settings, isLoading } = useQuery({
    queryKey: ["seo_settings"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("seo_settings")
        .select("*")
        .limit(1)
        .single();
      if (error) throw error;
      return data as SeoSettings;
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    const channel = supabase
      .channel("seo_settings_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "seo_settings" },
        () => {
          qc.invalidateQueries({ queryKey: ["seo_settings"] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [qc]);

  return { settings, isLoading };
}

export function useSeoPages() {
  const qc = useQueryClient();

  const { data: pages, isLoading } = useQuery({
    queryKey: ["seo_pages"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("seo_pages")
        .select("*")
        .order("page_path");
      if (error) throw error;
      return data as SeoPage[];
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    const channel = supabase
      .channel("seo_pages_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "seo_pages" },
        () => {
          qc.invalidateQueries({ queryKey: ["seo_pages"] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [qc]);

  return { pages: pages ?? [], isLoading };
}

export function useSeoPageByPath(path: string) {
  const { pages, isLoading } = useSeoPages();
  const page = pages.find((p) => p.page_path === path);
  return { page, isLoading };
}

