import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

Deno.serve(async (req) => {
  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    const [settingsRes, pagesRes] = await Promise.all([
      supabase
        .from("seo_settings")
        .select("sitemap_enabled, sitemap_changefreq, sitemap_priority, canonical_url")
        .limit(1)
        .single(),
      supabase
        .from("seo_pages")
        .select("page_path, changefreq, priority, include_in_sitemap, is_active")
        .eq("is_active", true)
        .eq("include_in_sitemap", true),
    ]);

    if (settingsRes.error) throw settingsRes.error;

    const settings = settingsRes.data;

    if (!settings?.sitemap_enabled) {
      return new Response("Sitemap is disabled", {
        status: 404,
        headers: { "Content-Type": "text/plain" },
      });
    }

    // Use configured canonical URL, fallback to request origin
    const baseUrl = (settings.canonical_url || "").replace(/\/$/, "") ||
      new URL(req.url).origin;

    const today = new Date().toISOString().split("T")[0];
    const pages = pagesRes.data ?? [];

    const urlEntries = pages
      .map((page: any) => {
        const priority = (page.priority ?? settings.sitemap_priority ?? 0.8).toFixed(1);
        const changefreq = page.changefreq || settings.sitemap_changefreq || "weekly";
        return `  <url>\n    <loc>${baseUrl}${page.page_path}</loc>\n    <lastmod>${today}</lastmod>\n    <changefreq>${changefreq}</changefreq>\n    <priority>${priority}</priority>\n  </url>`;
      })
      .join("\n");

    const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urlEntries}\n</urlset>`;

    return new Response(xml, {
      headers: {
        "Content-Type": "application/xml; charset=utf-8",
        "Cache-Control": "public, max-age=3600, s-maxage=3600",
      },
    });
  } catch (err) {
    console.error("serve-sitemap error:", err);
    return new Response("Error generating sitemap", {
      status: 500,
      headers: { "Content-Type": "text/plain" },
    });
  }
});

