toolUseResult.originalFile:
import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useSeoSettings } from "@/hooks/useSeoSettings";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { toast } from "sonner";
import { Save, Loader2, Bot, RotateCcw } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const DEFAULT_ROBOTS = `User-agent: *
Allow: /

# Block admin and auth pages from crawling
Disallow: /admin
Disallow: /settings

# Allow social media crawlers
User-agent: Googlebot
Allow: /

User-agent: Bingbot
Allow: /

User-agent: Twitterbot
Allow: /

User-agent: facebookexternalhit
Allow: /

Sitemap: /sitemap.xml`;

const RobotsTxtTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const [form, setForm] = useState({
    robots_txt: "",
    googlebot: "",
    bingbot: "",
  });

  if (settings && !loaded) {
    setForm({
      robots_txt: settings.robots_txt ?? DEFAULT_ROBOTS,
      googlebot: settings.googlebot ?? "",
      bingbot: settings.bingbot ?? "",
    });
    setLoaded(true);
  }

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("seo_settings")
        .update(form)
        .eq("id", settings?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Robots.txt settings saved");
      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "robots" });
      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    } finally {
      setSaving(false);
    }
  };

  const resetToDefault = () => {
    setForm({ ...form, robots_txt: DEFAULT_ROBOTS });
    toast.info("Reset to default. Click Save to apply.");
  };

  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg flex items-center gap-2"><Bot className="h-5 w-5" /> Robots.txt Editor</CardTitle>
              <CardDescription>Controls which pages search engine bots can crawl. This content will be served at /robots.txt</CardDescription>
            </div>
            <Button variant="outline" size="sm" onClick={resetToDefault}>
              <RotateCcw className="h-3 w-3 mr-1" /> Reset to Default
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <Textarea
            value={form.robots_txt}
            onChange={(e) => setForm({ ...form, robots_txt: e.target.value })}
            className="min-h-[300px] font-mono text-sm"
            placeholder="User-agent: *\nAllow: /"
          />
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label>Googlebot Specific Directive</Label>
              <Input value={form.googlebot} onChange={(e) => setForm({ ...form, googlebot: e.target.value })} placeholder="e.g. noindex, nofollow (leave empty for default)" />
              <p className="text-xs text-muted-foreground mt-1">Added as &lt;meta name="googlebot"&gt; if set</p>
            </div>
            <div>
              <Label>Bingbot Specific Directive</Label>
              <Input value={form.bingbot} onChange={(e) => setForm({ ...form, bingbot: e.target.value })} placeholder="e.g. noindex (leave empty for default)" />
              <p className="text-xs text-muted-foreground mt-1">Added as &lt;meta name="bingbot"&gt; if set</p>
            </div>
          </div>
        </CardContent>
      </Card>

      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save Robots Settings
      </Button>
    </div>
  );
};

export default RobotsTxtTab;

