import type { Result } from "@/pages/Index";

interface CandidateSummaryProps {
  result: Result;
}

const CandidateSummary = ({ result: r }: CandidateSummaryProps) => {
  const summary = r.explanation_json?.summary || r.summary;
  if (!summary) return null;

  return (
    <p className="text-sm leading-relaxed text-foreground max-w-3xl">
      {summary}
    </p>
  );
};

export default CandidateSummary;

