import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Mail, Phone, PhoneCall, CalendarClock } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";

interface ContactStripProps {
  candidateEmail?: string | null;
  candidatePhone?: string | null;
  candidateName: string;
  jobTitle: string;
  matchScore: number;
  resumeId: string;
  jobId: string;
}

const logOutreach = async (
  resumeId: string,
  jobId: string,
  type: string,
  toAddress: string
) => {
  try {
    const { data: { session } } = await supabase.auth.getSession();
    await (supabase as any).from("outreach_log").insert({
      resume_id: resumeId,
      job_id: jobId,
      type,
      to_address: toAddress,
      status: "logged",
      user_id: session?.user?.id ?? null,
    });
  } catch {
    // Non-critical — silently ignore logging failures
  }
};

const ContactStrip = ({
  candidateEmail,
  candidatePhone,
  candidateName,
  jobTitle,
  matchScore,
  resumeId,
  jobId,
}: ContactStripProps) => {
  const [emailOpen, setEmailOpen] = useState(false);

  if (!candidateEmail && !candidatePhone) return null;

  const handleSchedule = async () => {
    if (!candidatePhone) return;
    try {
      await navigator.clipboard.writeText(candidatePhone);
      toast.success("Call scheduled — phone number copied");
    } catch {
      toast.info(`Phone: ${candidatePhone}`);
    }
    await logOutreach(resumeId, jobId, "call_scheduled", candidatePhone);
  };

  const handleCallNow = async () => {
    if (!candidatePhone) return;
    await logOutreach(resumeId, jobId, "call_now", candidatePhone);
  };

  return (
    <>
      <div className="rounded-lg border bg-background px-4 py-3 flex flex-wrap items-center gap-x-6 gap-y-3">
        {/* Email section */}
        {candidateEmail && (
          <div className="flex items-center gap-3 min-w-0">
            <Mail className="h-4 w-4 text-muted-foreground shrink-0" />
            <span className="text-sm text-foreground truncate max-w-[200px]">{candidateEmail}</span>
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs shrink-0"
              onClick={() => setEmailOpen(true)}
            >
              Email
            </Button>
          </div>
        )}

        {candidateEmail && candidatePhone && (
          <div className="h-5 w-px bg-border shrink-0 hidden sm:block" />
        )}

        {/* Phone section */}
        {candidatePhone && (
          <div className="flex items-center gap-3 min-w-0">
            <Phone className="h-4 w-4 text-muted-foreground shrink-0" />
            <span className="text-sm text-foreground shrink-0">{candidatePhone}</span>
            <a href={`tel:${candidatePhone}`} onClick={handleCallNow}>
              <Button size="sm" variant="outline" className="h-7 text-xs gap-1.5">
                <PhoneCall className="h-3 w-3" /> Call Now
              </Button>
            </a>
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs gap-1.5"
              onClick={handleSchedule}
            >
              <CalendarClock className="h-3 w-3" /> Schedule
            </Button>
          </div>
        )}
      </div>

      {candidateEmail && (
        <EmailOutreachDialog
          open={emailOpen}
          onOpenChange={setEmailOpen}
          candidateName={candidateName}
          candidateEmail={candidateEmail}
          jobTitle={jobTitle}
          matchScore={matchScore}
          resumeId={resumeId}
          jobId={jobId}
        />
      )}
    </>
  );
};

export default ContactStrip;

