                          <Phone className="h-3.5 w-3.5" />
                        </Button>
                      </a>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Phone className="h-3.5 w-3.5" />
                      </Button>
