import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Search, ChevronLeft, ChevronRight, ClipboardList, Download, CalendarIcon, X } from "lucide-react";
import { format, startOfDay, endOfDay, subDays, startOfToday } from "date-fns";
import { cn } from "@/lib/utils";
import { exportToCSV } from "@/lib/csvExport";

interface AuditLog {
  id: string;
  admin_user_id: string;
  action: string;
  entity_type: string;
  entity_id: string | null;
  details: Record<string, any>;
  created_at: string;
}

const PAGE_SIZE = 30;

const actionColors: Record<string, string> = {
  create: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200",
  update: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200",
  delete: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
  toggle: "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200",
  ban: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
  unban: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200",
};

function getActionColor(action: string) {
  const verb = action.split(".").pop() ?? "";
  return actionColors[verb] ?? "";
}

const AuditLogsTab = () => {
  const [entityFilter, setEntityFilter] = useState("all");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0);
  const [dateFrom, setDateFrom] = useState<Date | undefined>();
  const [dateTo, setDateTo] = useState<Date | undefined>();

  const { data: logs, isLoading } = useQuery({
    queryKey: ["admin_audit_logs"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("admin_audit_logs")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(500);
      if (error) throw error;
      return data as AuditLog[];
    },
  });

  const { data: adminUsers } = useQuery({
    queryKey: ["admin_users_for_audit"],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
      if (error) throw error;
      return data as { id: string; email: string }[];
    },
  });

  const emailMap = useMemo(() => {
    const map = new Map<string, string>();
    adminUsers?.forEach((u) => map.set(u.id, u.email));
    return map;
  }, [adminUsers]);

  const filtered = logs?.filter((l) => {
    const matchesEntity = entityFilter === "all" || l.entity_type === entityFilter;
    const matchesSearch = !search || 
      l.action.toLowerCase().includes(search.toLowerCase()) ||
      l.entity_id?.toLowerCase().includes(search.toLowerCase()) ||
      JSON.stringify(l.details).toLowerCase().includes(search.toLowerCase());
    const logDate = new Date(l.created_at);
    const matchesFrom = !dateFrom || logDate >= startOfDay(dateFrom);
    const matchesTo = !dateTo || logDate <= endOfDay(dateTo);
    return matchesEntity && matchesSearch && matchesFrom && matchesTo;
  }) ?? [];

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  const entityTypes = [...new Set(logs?.map((l) => l.entity_type) ?? [])];

  return (
    <div className="space-y-4">
      <h2 className="text-xl font-semibold flex items-center gap-2">
        <ClipboardList className="h-5 w-5" /> Audit Logs
      </h2>

      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="relative">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search actions…"
                value={search}
                onChange={(e) => { setSearch(e.target.value); setPage(0); }}
                className="pl-8 w-[200px]"
              />
            </div>
            <Select value={entityFilter} onValueChange={(v) => { setEntityFilter(v); setPage(0); }}>
              <SelectTrigger className="w-[150px]"><SelectValue placeholder="Entity" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Entities</SelectItem>
                {entityTypes.map((e) => <SelectItem key={e} value={e}>{e}</SelectItem>)}
              </SelectContent>
            </Select>
            <Badge variant="outline" className="text-xs">{filtered.length} entries</Badge>

            {/* Preset date ranges */}
            {[
              { label: "Today", from: startOfToday(), to: new Date() },
              { label: "7 days", from: subDays(new Date(), 7), to: new Date() },
              { label: "30 days", from: subDays(new Date(), 30), to: new Date() },
            ].map((preset) => (
              <Button
                key={preset.label}
                variant="outline"
                size="sm"
                className="text-xs h-7"
                onClick={() => { setDateFrom(preset.from); setDateTo(preset.to); setPage(0); }}
              >
                {preset.label}
              </Button>
            ))}

            {/* Date range pickers */}
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className={cn("gap-1", !dateFrom && "text-muted-foreground")}>
                  <CalendarIcon className="h-3.5 w-3.5" />
                  {dateFrom ? format(dateFrom, "MMM d, yyyy") : "From"}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar mode="single" selected={dateFrom} onSelect={(d) => { setDateFrom(d); setPage(0); }} initialFocus className="p-3 pointer-events-auto" />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className={cn("gap-1", !dateTo && "text-muted-foreground")}>
                  <CalendarIcon className="h-3.5 w-3.5" />
                  {dateTo ? format(dateTo, "MMM d, yyyy") : "To"}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar mode="single" selected={dateTo} onSelect={(d) => { setDateTo(d); setPage(0); }} initialFocus className="p-3 pointer-events-auto" />
              </PopoverContent>
            </Popover>
            {(dateFrom || dateTo) && (
              <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => { setDateFrom(undefined); setDateTo(undefined); setPage(0); }}>
                <X className="h-3.5 w-3.5" />
              </Button>
            )}
            <Button
              variant="outline"
              size="sm"
              disabled={filtered.length === 0}
              onClick={() => exportToCSV(
                filtered.map((l) => ({
                  time: format(new Date(l.created_at), "yyyy-MM-dd HH:mm:ss"),
                  admin: emailMap.get(l.admin_user_id) ?? l.admin_user_id,
                  action: l.action,
                  entity_type: l.entity_type,
                  entity_id: l.entity_id ?? "",
                  details: JSON.stringify(l.details),
                })),
                "audit-logs"
              )}
            >
              <Download className="h-3.5 w-3.5 mr-1" />Export CSV
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Time</TableHead>
                <TableHead>Admin</TableHead>
                <TableHead>Action</TableHead>
                <TableHead>Entity</TableHead>
                <TableHead>Entity ID</TableHead>
                <TableHead>Details</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow><TableCell colSpan={6} className="text-center py-8 text-muted-foreground">Loading…</TableCell></TableRow>
              ) : paged.length === 0 ? (
                <TableRow><TableCell colSpan={6} className="text-center py-8 text-muted-foreground">No audit logs found</TableCell></TableRow>
              ) : paged.map((l) => (
                <TableRow key={l.id}>
                  <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                    {format(new Date(l.created_at), "MMM d, HH:mm:ss")}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                    {emailMap.get(l.admin_user_id) ?? l.admin_user_id.slice(0, 8) + "…"}
                  </TableCell>
                  <TableCell>
                    <Badge variant="secondary" className={`text-xs ${getActionColor(l.action)}`}>
                      {l.action}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm">{l.entity_type}</TableCell>
                  <TableCell className="text-xs font-mono text-muted-foreground max-w-[120px] truncate">
                    {l.entity_id ?? "—"}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground max-w-[250px] truncate">
                    {Object.keys(l.details).length > 0 ? JSON.stringify(l.details) : "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
              <div className="flex items-center gap-2">
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
                  <ChevronLeft className="h-3.5 w-3.5" />
                </Button>
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
                  <ChevronRight className="h-3.5 w-3.5" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default AuditLogsTab;

