import { useState, useMemo } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import {
  Search, ChevronLeft, ChevronRight, AlertTriangle, Download,
  CheckCircle, Eye, X,
} from "lucide-react";
import { format, subDays, startOfDay, endOfDay, startOfToday } from "date-fns";
import { exportToCSV } from "@/lib/csvExport";
import { toast } from "sonner";

interface SystemError {
  id: string;
  created_at: string;
  function_name: string;
  error_type: string;
  severity: string;
  user_id: string | null;
  job_id: string | null;
  resume_id: string | null;
  error_message: string;
  error_stack: string | null;
  context_json: Record<string, any>;
  is_resolved: boolean;
  resolved_at: string | null;
  resolution_notes: string | null;
}

const PAGE_SIZE = 30;

const severityColors: Record<string, string> = {
  critical: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300",
  warning: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300",
  info: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300",
};

const SystemErrorLogsTab = () => {
  const qc = useQueryClient();
  const [fnFilter, setFnFilter] = useState("all");
  const [severityFilter, setSeverityFilter] = useState("all");
  const [resolvedFilter, setResolvedFilter] = useState("unresolved");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const { data: errors, isLoading } = useQuery({
    queryKey: ["system_error_logs"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("system_error_logs")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(500);
      if (error) throw error;
      return data as SystemError[];
    },
    refetchInterval: 30000,
  });

  const filtered = useMemo(() => {
    return (errors ?? []).filter((e) => {
      if (fnFilter !== "all" && e.function_name !== fnFilter) return false;
      if (severityFilter !== "all" && e.severity !== severityFilter) return false;
      if (resolvedFilter === "unresolved" && e.is_resolved) return false;
      if (resolvedFilter === "resolved" && !e.is_resolved) return false;
      if (search) {
        const q = search.toLowerCase();
        return (
          e.error_message.toLowerCase().includes(q) ||
          e.error_type.toLowerCase().includes(q) ||
          e.function_name.toLowerCase().includes(q) ||
          (e.resume_id?.toLowerCase().includes(q) ?? false) ||
          (e.job_id?.toLowerCase().includes(q) ?? false)
        );
      }
      return true;
    });
  }, [errors, fnFilter, severityFilter, resolvedFilter, search]);

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  const functionNames = [...new Set(errors?.map((e) => e.function_name) ?? [])].sort();

  const criticalCount = (errors ?? []).filter((e) => e.severity === "critical" && !e.is_resolved).length;
  const unresolvedCount = (errors ?? []).filter((e) => !e.is_resolved).length;

  const markResolved = async (id: string) => {
    const { error } = await (supabase as any)
      .from("system_error_logs")
      .update({ is_resolved: true, resolved_at: new Date().toISOString() })
      .eq("id", id);
    if (error) { toast.error(error.message); return; }
    toast.success("Marked as resolved");
    qc.invalidateQueries({ queryKey: ["system_error_logs"] });
  };

  return (
    <div className="space-y-4">
      <h2 className="text-xl font-semibold flex items-center gap-2">
        <AlertTriangle className="h-5 w-5" /> System Error Logs
        {criticalCount > 0 && (
          <Badge variant="destructive" className="text-xs ml-2">{criticalCount} critical</Badge>
        )}
        {unresolvedCount > 0 && (
          <Badge variant="outline" className="text-xs">{unresolvedCount} unresolved</Badge>
        )}
      </h2>

      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="relative">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search errors..."
                value={search}
                onChange={(e) => { setSearch(e.target.value); setPage(0); }}
                className="pl-8 w-[200px]"
              />
            </div>
            <Select value={fnFilter} onValueChange={(v) => { setFnFilter(v); setPage(0); }}>
              <SelectTrigger className="w-[170px]"><SelectValue placeholder="Function" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Functions</SelectItem>
                {functionNames.map((fn) => <SelectItem key={fn} value={fn}>{fn}</SelectItem>)}
              </SelectContent>
            </Select>
            <Select value={severityFilter} onValueChange={(v) => { setSeverityFilter(v); setPage(0); }}>
              <SelectTrigger className="w-[130px]"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Severity</SelectItem>
                <SelectItem value="critical">Critical</SelectItem>
                <SelectItem value="warning">Warning</SelectItem>
                <SelectItem value="info">Info</SelectItem>
              </SelectContent>
            </Select>
            <Select value={resolvedFilter} onValueChange={(v) => { setResolvedFilter(v); setPage(0); }}>
              <SelectTrigger className="w-[140px]"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="unresolved">Unresolved</SelectItem>
                <SelectItem value="resolved">Resolved</SelectItem>
              </SelectContent>
            </Select>
            <Badge variant="outline" className="text-xs">{filtered.length} entries</Badge>
            <Button
              variant="outline" size="sm" disabled={filtered.length === 0}
              onClick={() => exportToCSV(
                filtered.map((e) => ({
                  time: format(new Date(e.created_at), "yyyy-MM-dd HH:mm:ss"),
                  function: e.function_name,
                  type: e.error_type,
                  severity: e.severity,
                  message: e.error_message,
                  job_id: e.job_id ?? "",
                  resume_id: e.resume_id ?? "",
                  resolved: e.is_resolved ? "Yes" : "No",
                })),
                "system-errors"
              )}
            >
              <Download className="h-3.5 w-3.5 mr-1" /> Export CSV
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[130px]">Time</TableHead>
                <TableHead>Function</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Severity</TableHead>
                <TableHead className="max-w-[300px]">Message</TableHead>
                <TableHead>Context</TableHead>
                <TableHead className="w-[80px]">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow><TableCell colSpan={7} className="text-center py-8 text-muted-foreground">Loading...</TableCell></TableRow>
              ) : paged.length === 0 ? (
                <TableRow><TableCell colSpan={7} className="text-center py-8 text-muted-foreground">No errors found</TableCell></TableRow>
              ) : paged.map((e) => (
                <TableRow key={e.id} className={e.is_resolved ? "opacity-50" : ""}>
                  <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                    {format(new Date(e.created_at), "MMM d, HH:mm:ss")}
                  </TableCell>
                  <TableCell className="text-xs font-mono">{e.function_name}</TableCell>
                  <TableCell>
                    <Badge variant="outline" className="text-[10px]">{e.error_type}</Badge>
                  </TableCell>
                  <TableCell>
                    <Badge className={`text-[10px] ${severityColors[e.severity] ?? ""}`}>
                      {e.severity}
                    </Badge>
                  </TableCell>
                  <TableCell className="max-w-[300px]">
                    <p className="text-xs text-muted-foreground truncate" title={e.error_message}>
                      {e.error_message}
                    </p>
                    {expandedId === e.id && e.error_stack && (
                      <pre className="text-[10px] font-mono bg-muted p-2 rounded mt-1 max-h-32 overflow-auto whitespace-pre-wrap">
                        {e.error_stack}
                      </pre>
                    )}
                  </TableCell>
                  <TableCell className="text-xs text-muted-foreground">
                    {e.job_id && <span className="block font-mono truncate max-w-[100px]">job:{e.job_id.slice(0, 8)}</span>}
                    {e.resume_id && <span className="block font-mono truncate max-w-[100px]">res:{e.resume_id.slice(0, 8)}</span>}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-0.5">
                      <TooltipProvider delayDuration={200}>
                        {e.error_stack && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => setExpandedId(expandedId === e.id ? null : e.id)}>
                                <Eye className="h-3 w-3" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">View stack trace</TooltipContent>
                          </Tooltip>
                        )}
                        {!e.is_resolved && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button variant="ghost" size="icon" className="h-6 w-6 text-emerald-600" onClick={() => markResolved(e.id)}>
                                <CheckCircle className="h-3 w-3" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent className="text-xs">Mark resolved</TooltipContent>
                          </Tooltip>
                        )}
                      </TooltipProvider>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
              <div className="flex items-center gap-2">
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
                  <ChevronLeft className="h-3.5 w-3.5" />
                </Button>
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
                  <ChevronRight className="h-3.5 w-3.5" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default SystemErrorLogsTab;

