import {
  LayoutDashboard, Users, CreditCard, Settings, Plug, ScrollText, Mail, BrainCircuit,
  Eye, UserCog, Wrench, Server, ClipboardList, Search,
} from "lucide-react";
import { cn } from "@/lib/utils";

const sectionGroups = [
  {
    label: "Overview",
    icon: Eye,
    items: [
      { key: "dashboard", label: "Dashboard", icon: LayoutDashboard },
    ],
  },
  {
    label: "Users & Billing",
    icon: UserCog,
    items: [
      { key: "users", label: "Users", icon: Users },
      { key: "billing", label: "Billing & Plans", icon: CreditCard },
    ],
  },
  {
    label: "Configuration",
    icon: Wrench,
    items: [
      { key: "platform_settings", label: "Platform Settings", icon: Settings },
      { key: "email_settings", label: "Email Settings", icon: Mail },
      { key: "ai_prompts", label: "AI Prompts", icon: BrainCircuit },
      { key: "seo", label: "SEO", icon: Search },
    ],
  },
  {
    label: "System",
    icon: Server,
    items: [
      { key: "integrations", label: "Integrations", icon: Plug },
      { key: "logs", label: "Usage Logs", icon: ScrollText },
      { key: "audit_logs", label: "Audit Logs", icon: ClipboardList },
    ],
  },
] as const;

type SectionItem = (typeof sectionGroups)[number]["items"][number];
export type AdminSection = SectionItem["key"];

interface AdminSidebarProps {
  active: AdminSection;
  onSelect: (section: AdminSection) => void;
}

const AdminSidebar = ({ active, onSelect }: AdminSidebarProps) => {
  return (
    <aside className="w-56 shrink-0 border-r border-border bg-card min-h-[calc(100vh-3.5rem)]">
      <nav className="flex flex-col gap-1 p-3">
        {sectionGroups.map((group, gi) => {
          const GroupIcon = group.icon;
          return (
            <div key={group.label} className="animate-in fade-in slide-in-from-left-2 duration-300" style={{ animationDelay: `${gi * 75}ms`, animationFillMode: "backwards" }}>
              {gi > 0 && <div className="my-2 h-px bg-border" />}
              <span className="group/header flex items-center gap-1.5 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
                <GroupIcon className="h-3 w-3 shrink-0 opacity-60 transition-transform duration-200 group-hover/header:scale-110" />
                {group.label}
              </span>
              {group.items.map(({ key, label, icon: Icon }) => (
                <button
                  key={key}
                  onClick={() => onSelect(key)}
                  className={cn(
                    "flex items-center gap-2.5 rounded-md px-3 py-2 text-sm font-medium transition-all duration-200 text-left w-full",
                    active === key
                      ? "bg-primary/10 text-primary"
                      : "text-muted-foreground hover:bg-accent hover:text-accent-foreground hover:translate-x-0.5"
                  )}
                >
                  <Icon className="h-4 w-4 shrink-0 transition-transform duration-200" />
                  {label}
                </button>
              ))}
            </div>
          );
        })}
      </nav>
    </aside>
  );
};

export default AdminSidebar;

